// DB return types
export interface GuestbookRow {
  id: string;
  reply: string | null;
  date: string;
  name: string;
  message: string;
  website: string | null;
}

// For inserts (omit auto-generated fields)
export interface MessageInsert {
  // id omitted, generated by the db.ts func
  reply: string | null;
  // date omitted
  name: string;
  message: string;
  // visible omitted
  website: string | null;
}

// Other
export interface LastFmProxyParams {
  method: string;
}

export interface LastFmProxyQuery {
  user?: string;
  [key: string]: string | undefined;
}

export interface Message {
  id: string; // UUID v4
  reply: string | null; // UUID v4 of the original comment
  replies: Message[];
  date: Date;
  name: string;
  message: string;
  // visible: boolean; not shown to the user
  website: string | null;
}

export class InvalidReplyError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "InvalidReplyError";
    // Set the prototype explicitly to maintain the correct prototype chain
    Object.setPrototypeOf(this, InvalidReplyError.prototype);
  }
}

// POST types

export const POST_guestbookSchema = {
  body: {
    type: "object",
    required: ["name", "message"],
    additionalProperties: false,
    properties: {
      name: {
        type: "string",
        minLength: 1,
        maxLength: process.env.GUESTBOOK_MAX_NAME_LEN,
      },
      message: {
        type: "string",
        minLength: 1,
        maxLength: process.env.GUESTBOOK_MAX_MESSAGE_LEN,
      },
      reply: {
        anyOf: [{ type: "string", format: "uuid" }, { type: "null" }],
      },
      website: {
        anyOf: [{ type: "string", minLength: 1 }, { type: "null" }],
      },
    },
  },
} as const;

export const POST_ntfy = {
  body: {
    type: "object",
    required: ["message"],
    additionalProperties: false,
    properties: {
      message: {
        type: "string",
        minLength: 1,
      },
    },
  },
} as const;

export interface POST_Message {
  name: string;
  message: string;
  reply?: string | null;
  website?: string | null;
}
